// Throwaway stress probe for the gh-2425 rework: replays the E2 scenario
// N times in one process to hunt a nondeterministic abort path. Not part
// of the repo test tree — run manually, then deleted.
@TestOn('vm')
library;

import 'dart:math';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:test/test.dart';

DateTime clockNow = DateTime(2026, 1, 10, 12);
DateTime clock() => clockNow;
DateTime daysAgo(int age) => clockNow.subtract(Duration(days: age));

final class _FlippingPresence implements SessionPresenceStore {
  _FlippingPresence({
    required this.delegate,
    required this.lateLiveId,
    required this.liveFromCall,
  });

  final SessionPresenceStore delegate;
  final String lateLiveId;
  final int liveFromCall;
  int calls = 0;

  @override
  Future<void> register(String sessionId, {int? pid, String? host}) =>
      delegate.register(sessionId, pid: pid, host: host);

  @override
  Future<void> touch(String sessionId) => delegate.touch(sessionId);

  @override
  Future<void> unregister(String sessionId) => delegate.unregister(sessionId);

  @override
  Future<Map<String, SessionPresence>> list() async {
    final all = await delegate.list();
    final call = calls++;
    if (call >= liveFromCall - 1) return all;
    return {
      for (final entry in all.entries)
        if (entry.key != lateLiveId) entry.key: entry.value,
    };
  }
}

void main() {
  test('E2 stress x100', () async {
    var failures = 0;
    for (var i = 0; i < 100; i++) {
      clockNow = DateTime(2026, 1, 10, 12);
      final env = MemoryExecutionEnv(cwd: '/work');
      final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
      final presence = FileSessionPresenceStore(env: env, root: '/sessions', now: clock);

      Future<String> seedSession({
        DateTime? createdAt,
        DateTime? lastUsed,
        int sizeBytes = 0,
      }) async {
        final session = await repo.create(JsonlSessionCreateOptions(cwd: '/work'));
        if (sizeBytes > 0) {
          await session.appendMessage(UserMessage.text('x' * sizeBytes));
        }
        final metadata = await session.getMetadata();
        if (createdAt != null) {
          final raw = (await env.readTextFile(metadata.path)).valueOrNull!;
          await env.writeFile(
            metadata.path,
            raw.replaceFirst(
              RegExp(r'"timestamp":"[^"]+"'),
              '"timestamp":"${createdAt.toIso8601String()}"',
            ),
          );
        }
        env.setMtime(
          metadata.path,
          (lastUsed ?? createdAt ?? clockNow).millisecondsSinceEpoch,
        );
        return metadata.id;
      }

      final a = await seedSession(createdAt: daysAgo(90), sizeBytes: 100, lastUsed: daysAgo(60));
      final b = await seedSession(createdAt: daysAgo(90), sizeBytes: 100, lastUsed: daysAgo(59));
      await presence.register(b);
      final usage = await SessionRetentionSweeper(
        fs: env,
        sessionsRoot: '/sessions',
        retention: const SessionRetentionConfig(),
        presenceStore: presence,
        now: clock,
        currentSessionId: null,
      ).usage();
      final unit = usage.sessions.first.bytes;
      final flipping = _FlippingPresence(
        delegate: presence,
        lateLiveId: b,
        liveFromCall: 3,
      );
      final report = await SessionRetentionSweeper(
        fs: env,
        sessionsRoot: '/sessions',
        retention: SessionRetentionConfig(
          maxTotalBytes: usage.totalBytes - unit * 2 + 1,
          minAgeDays: 0,
        ),
        presenceStore: flipping,
        now: clock,
        currentSessionId: null,
      ).sweep(dryRun: false);
      final deleted = report.deletions.map((d) => d.sessionId).toSet();
      if (!deleted.contains(a) || report.applied != true || flipping.calls != 3) {
        failures++;
        // ignore: avoid_print
        print('iteration $i FAILED: deleted=$deleted applied=${report.applied} '
            'calls=${flipping.calls} cap=${usage.totalBytes - unit * 2 + 1} '
            'total=${usage.totalBytes} unit=$unit notes=${report.notes} '
            'log=${report.logLines}');
      }
    }
    expect(failures, 0, reason: '$failures/100 iterations diverged');
  });
}

