+    for (const [name, value] of Object.entries(raw)) {
+      const n = String(name).trim().toLowerCase();
+      const v = typeof value === 'string' ? value.trim() : '';
+      if (!n || !v) continue;
+      headers[n] = v;
+    }
+  }
+  return headers;
+}
